async function feeSummary(studentId:string,term:string,rows:(t:string,q?:string)=>Promise<any[]>){const inv=await rows('invoices',`?student_id=eq.${studentId}&term=eq.${enc(term)}&select=*,invoice_lines(*),payments(*)`);let charges=0,paid=0;const statement:any[]=[];for(const i of inv){for(const l of i.invoice_lines||[]){charges+=Number(l.amount);statement.push({description:l.description,charge:String(l.amount),payment:'0'})}for(const p of i.payments||[]){if(p.status==='verified')paid+=Number(p.amount);statement.push({description:`${p.method} · ${p.transaction_reference}`,charge:'0',payment:String(p.amount),status:p.status,receipt:p.receipt_number||''})}}const c=(await rows('enrolment_cases',`?student_id=eq.${studentId}&select=applicant_id`))[0];if(c){const prior=await rows('payments',`?applicant_id=eq.${c.applicant_id}&select=*`);for(const p of prior){if(p.status==='verified')paid+=Number(p.amount);statement.push({description:`Admission payment · ${p.transaction_reference}`,charge:'0',payment:String(p.amount),status:p.status,receipt:p.receipt_number||''})}}return{balance:String(charges-paid),statement,invoices:inv.map((i:any)=>({id:i.id,number:i.invoice_number,term:i.term,status:i.status,dueOn:i.due_on,total:String((i.invoice_lines||[]).reduce((n:number,l:any)=>n+Number(l.amount),0))}))}}
