function decodeUpload(raw:string,name:string){const match=raw.match(/^data:(application\/pdf|image\/(?:jpeg|png));base64,([\s\S]+)$/);if(!match)throw new Error('Upload a PDF, JPEG or PNG document.');const bytes=Uint8Array.from(atob(match[2]),c=>c.charCodeAt(0));if(bytes.length>10*1024*1024)throw new Error('Files must be 10 MB or smaller.');const sig=[...bytes.slice(0,8)];const valid=match[1]==='application/pdf'?new TextDecoder().decode(bytes.slice(0,5))==='%PDF-':match[1]==='image/jpeg'?sig[0]===255&&sig[1]===216&&sig[2]===255:sig.join(',')==='137,80,78,71,13,10,26,10';if(!valid)throw new Error('The uploaded file does not match its type.');const safe=name.replace(/[^\w.-]/g,'_').slice(-100)||'upload';return{bytes:bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength) as ArrayBuffer,type:match[1],name:safe}}
